contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take inputs to drive different scenarios:
    // - callerIsOperator: whether we will mark this contract as a program operator before calling create
    // - encodedParameters and ownedBy are forwarded to create
    // Note: this contract is the msg.sender for calls to c.
    function run(bool callerIsOperator, bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Read initial observable state
        address initialOwner = c.owner(); if (__ESBMC_reverted()) return;
        address initialRoundImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address initialAllo = c.alloSettings(); if (__ESBMC_reverted()) return;

        // If callerIsOperator, set programOperators[msg.sender] via direct storage is not possible here.
        // But we can simulate granting operator by calling any owner-only function to set programOperators mapping is not exposed.
        // The contract C has public mapping programOperators but no setter; however owner can set it only via direct storage which isn't exposed.
        // Therefore we instead check two general behaviors combined into one assertion:
        // 1) If roundImplementation==0 or alloSettings==0 then create must revert regardless of operator registration.
        // 2) If roundImplementation!=0 and alloSettings!=0 then either create reverts (if caller not operator) or returns a non-zero address (if caller is operator).
        // We will attempt the create call and record whether it reverted.

        bool reverted;
        address returnedAddress;
        c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            // If it didn't revert, we can try to capture the returned value by calling again is not allowed; but try returns no value here.
            // So fetch nothing; we will treat non-revert as success for the purposes of the assertion.
        }

        // Re-read observable state after the call
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        address afterRoundImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address afterAllo = c.alloSettings(); if (__ESBMC_reverted()) return;

        // Now assert the general rule as a single boolean expression:
        // - Owner must never change as a result of create (onlyProgramOperator modifier doesn't change owner)
        // - If either roundImplementation or alloSettings was zero before the call, create must revert
        // - If both were non-zero before the call and the call did not revert, then it must have returned/created something: observed by the fact the call did not revert (we cannot observe clone addr), and factory's roundImplementation and alloSettings remain equal to before
        assert(
            // owner is invariant
            afterOwner == initialOwner
            &&
            (
                // case: missing implementation or settings => must revert
                (initialRoundImpl == address(0) || initialAllo == address(0)) ? reverted
                :
                // case: both set => if call succeeded (not reverted) then roundImpl and alloSettings unchanged; if reverted that's allowed
                (reverted || (afterRoundImpl == initialRoundImpl && afterAllo == initialAllo))
            )
        );
    }

    receive() external payable { }
 }

