pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(bool callerIsOperator, bytes memory encodedParameters, address ownedBy) internal {
        vm.assume(true);
        address initialOwner;
        try c.owner() returns (address __r) { initialOwner = __r; } catch { return; }
        address initialRoundImpl;
        try c.roundImplementation() returns (address __r) { initialRoundImpl = __r; } catch { return; }
        address initialAllo;
        try c.alloSettings() returns (address __r) { initialAllo = __r; } catch { return; }
        bool reverted;
        address returnedAddress;
        try c.create(encodedParameters, ownedBy) {
            reverted = false;
            // If it didn't revert, we can try to capture the returned value by calling again is not allowed; but try returns no value here.
            // So fetch nothing; we will treat non-revert as success for the purposes of the assertion.
        } catch {
            reverted = true;
        }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        address afterRoundImpl;
        try c.roundImplementation() returns (address __r) { afterRoundImpl = __r; } catch { return; }
        address afterAllo;
        try c.alloSettings() returns (address __r) { afterAllo = __r; } catch { return; }
        assertTrue(afterOwner == initialOwner
            &&
            (
                // case: missing implementation or settings => must revert
                (initialRoundImpl == address(0) || initialAllo == address(0)) ? reverted
                :
                // case: both set => if call succeeded (not reverted) then roundImpl and alloSettings unchanged; if reverted that's allowed
                (reverted || (afterRoundImpl == initialRoundImpl && afterAllo == initialAllo))
            ));
    }

    function testFuzz_run(bool callerIsOperator, bytes memory encodedParameters, address ownedBy) public {
        vm.assume(ownedBy.code.length == 0 && uint160(ownedBy) > 0xffff && ownedBy != address(this) && ownedBy != address(c) && ownedBy != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && ownedBy != 0x000000000000000000636F6e736F6c652e6c6f67 && ownedBy != 0x4e59b44847b379578588920cA78FbF26c0B4956C && ownedBy != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(callerIsOperator, encodedParameters, ownedBy);
    }

    receive() external payable { }
}
